const serviceKey = 'sb_secret_b0IcObDVlfwIlKpClSJD_Q_bAAK8DxJ';
const scrapeApiKey = ''; // Điền key ScrapeCreators tại đây nếu kết nối API trực tiếp

// 1. LẤY GIÁ NIÊM YẾT CHUẨN TỪ WEBSITE (Chỉ lấy tên món và giá tiền, tuyệt đối KHÔNG lấy ảnh web)
let products = [];
try {
  const res = await fetch('https://bnblofcypxfydnptazrs.supabase.co/rest/v1/products?category_id=eq.1a111111-1111-1111-1111-111111111111&is_available=eq.true&select=name_vi,price', {
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey }
  });
  products = await res.json();
} catch (e) {}

if (!products || !products.length) {
  products = [
    { name_vi: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI", price: 55000 },
    { name_vi: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI", price: 70000 },
    { name_vi: "SANDWICH TRỨNG PHÔ MAI", price: 40000 },
    { name_vi: "SANDWICH DĂM BÔNG PHÔ MAI MỸ", price: 50000 },
    { name_vi: "SANDWICH GÀ NƯỚNG PESTO", price: 60000 },
    { name_vi: "SANDWICH THỊT HỘP, PHÔ MAI & NORI", price: 60000 },
    { name_vi: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI", price: 50000 },
    { name_vi: "SANDWICH CÁ NGỪ PHÔ MAI", price: 60000 },
    { name_vi: "SANDWICH NƯỚNG KIỂU PHÁP", price: 55000 }
  ];
}

// 2. KHO ẢNH THẬT 100% TỪ MẠNG XÃ HỘI (ẢNH ĐỜI THỰC CHỤP TẠI BÀN, DẠO PHỐ, FEED SOCIAL)
// Tuyệt đối KHÔNG DÙNG ảnh nền trắng catalog của website
const realSocialPhotos = [
  {
    source: "Threads",
    sourceHandle: "@hhnh_7410",
    dishName: "SANDWICH THỊT XÔNG KHÓI BƠ TỎI PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7701629125517135112.jpg"
  },
  {
    source: "Instagram",
    sourceHandle: "@eggu_sandwich",
    dishName: "SANDWICH THỊT BÒ NƯỚNG TERIYAKI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7696731856955378996.jpg"
  },
  {
    source: "Facebook",
    sourceHandle: "EGGU Fanpage",
    dishName: "SANDWICH TRỨNG PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7695023597147933959.jpg"
  },
  {
    source: "Threads",
    sourceHandle: "@hanoifoodie_eat",
    dishName: "SANDWICH THỊT HỘP, PHÔ MAI & NORI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7698288809108065537.jpg"
  },
  {
    source: "Instagram",
    sourceHandle: "@eggu_sandwich",
    dishName: "SANDWICH GÀ NƯỚNG PESTO",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7700504799107714322.jpg"
  },
  {
    source: "Threads",
    sourceHandle: "@linhchi_walk",
    dishName: "SANDWICH THỊT XÔNG KHÓI NGÔ PHÔ MAI",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7702745741395053842.jpg"
  },
  {
    source: "Facebook",
    sourceHandle: "EGGU Fanpage",
    dishName: "SANDWICH NƯỚNG KIỂU PHÁP",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7700879242501967112.jpg"
  },
  {
    source: "Instagram",
    sourceHandle: "@eggu_sandwich",
    dishName: "SANDWICH DĂM BÔNG PHÔ MAI MỸ",
    photoUrl: "https://bnblofcypxfydnptazrs.supabase.co/storage/v1/object/public/news/tiktok-7691901190380064018.jpg"
  }
];

// Chọn ngẫu nhiên 1 bức ảnh chụp thực tế từ Social
const picked = realSocialPhotos[Math.floor(Math.random() * realSocialPhotos.length)];
const matchedProduct = products.find(p => p.name_vi === picked.dishName) || products[0];

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "";
let suggestedTheme = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  angle = "Đồng hành công sở (Bữa sáng vội vã, ăn sạch tay không dính mỡ, no lâu, gom đơn cùng đồng nghiệp)";
  suggestedTheme = "morning_commute";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  angle = "Cứu đói xế chiều 14h - 16h (Thèm phô mai kéo sợi ngập tràn, tiếp năng lượng giờ làm việc uể oải)";
  suggestedTheme = "street_bold";
} else if (dayOfWeek === 5) {
  angle = "Nạp năng lượng cuối tuần (Tự thưởng cho bản thân bữa ăn nóng hổi chất lượng chuẩn vị Seoul)";
  suggestedTheme = "seoul_cafe";
} else {
  angle = "Dạo phố cổ Hồ Gươm (Bánh nướng nóng hổi cầm tay dạo quanh phố 54 Nguyễn Hữu Huân)";
  suggestedTheme = "hanoi_vintage";
}

const formattedPrice = Number(matchedProduct.price).toLocaleString('vi-VN') + 'đ';

return [
  {
    json: {
      dishName: matchedProduct.name_vi,
      dishPrice: formattedPrice,
      dishPriceRaw: matchedProduct.price,
      photoUrl: picked.photoUrl,
      socialSource: picked.source,
      sourceHandle: picked.sourceHandle,
      photoTag: picked.source + ' (' + picked.sourceHandle + ')',
      targetAngle: angle,
      suggestedTheme: suggestedTheme,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "eggu.vn"
    }
  }
];

let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    poster_headline: 'NÓNG HỔI VỪA THỔI VỪA ĂN',
    poster_subline: 'Bánh mì brioche nướng bơ tỏi đẫm trứng fluffy và phô mai',
    poster_badge: 'BÁN CHẠY NHẤT',
    theme: $('Code - Lấy Ảnh Thật Từ Social (FB, IG, Threads)').item.json.suggestedTheme || 'street_bold',
    dish: $('Code - Lấy Ảnh Thật Từ Social (FB, IG, Threads)').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

const dishInfo = $('Code - Lấy Ảnh Thật Từ Social (FB, IG, Threads)').item.json;
const chosenTheme = parsed.theme || dishInfo.suggestedTheme || 'street_bold';
const headline = parsed.poster_headline || 'NÓNG HỔI VỪA THỔI VỪA ĂN';
const subline = parsed.poster_subline || (dishInfo.dishName + ' - Bánh nướng bơ tỏi giòn rụm');
const badge = parsed.poster_badge || 'BÁN CHẠY NHẤT';

// Tạo link Poster Đồ Họa 1080x1080 do Code sinh ra từ CHÍNH BỨC ẢNH THẬT TỪ SOCIAL
const posterUrl = 'http://localhost:3000/api/marketing/poster?' +
  'dish=' + encodeURIComponent(dishInfo.dishName) +
  '&price=' + encodeURIComponent(dishInfo.dishPrice) +
  '&headline=' + encodeURIComponent(headline) +
  '&subline=' + encodeURIComponent(subline) +
  '&badge=' + encodeURIComponent(badge) +
  '&theme=' + encodeURIComponent(chosenTheme) +
  '&image=' + encodeURIComponent(dishInfo.photoUrl);

return [
  {
    json: {
      title: parsed.title || ('EGGU - ' + dishInfo.dishName),
      dishName: dishInfo.dishName,
      dishCategory: dishInfo.photoTag,
      dishPrice: dishInfo.dishPrice,
      targetAngle: dishInfo.targetAngle,
      content: parsed.content || rawText,
      realPhotoUrl: dishInfo.photoUrl,
      aiPhotoUrl: posterUrl,
      posterTheme: chosenTheme,
      status: 'PENDING',
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || ('EGGU - ' + dishInfo.dishName),
      'Món ăn': dishInfo.dishName + ' (Giá web: ' + dishInfo.dishPrice + ')',
      'Nguồn ảnh': dishInfo.photoTag,
      'Nội dung Facebook (Đã biên tập)': parsed.content || rawText,
      '📸 ẢNH THẬT (Social)': dishInfo.photoUrl,
      '🎨 POSTER ĐỒ HỌA 1080x1080 (AI & Code sinh từ ảnh thật)': posterUrl,
      'Phong cách Poster': chosenTheme,
      'Gợi ý đăng bài': 'Đăng bài kèm ảnh thật hoặc poster đồ họa 1080x1080!',
      'Trạng thái': 'Chờ nhân viên copy',
      'Thời gian tạo': new Date().toLocaleString('vi-VN')
    }
  }
];
